import{_ as a,o as t,c as o,ae as i}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"ADR 035: Reaching 100% Domain Coverage","description":"","frontmatter":{},"headers":[],"relativePath":"adr/035-reaching-100-domain-coverage.md","filePath":"adr/035-reaching-100-domain-coverage.md"}'),n={name:"adr/035-reaching-100-domain-coverage.md"};function r(c,e,s,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-035-reaching-100-domain-coverage" tabindex="-1">ADR 035: Reaching 100% Domain Coverage <a class="header-anchor" href="#adr-035-reaching-100-domain-coverage" aria-label="Permalink to &quot;ADR 035: Reaching 100% Domain Coverage&quot;">​</a></h1><h2 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h2><p>2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>As part of the project&#39;s quality standards, we aimed to reach 100% function and branch coverage for the <code>src/domain</code> layer. This layer contains the core business logic (Rules, Entities, Repositories, and Extractors) and must be absolutely reliable.</p><p>Previously, coverage was at ~77%. Specific gaps were identified in:</p><ul><li><code>ScopeValidationRule</code>: Undefined requirements case.</li><li><code>RequirementsExtractor</code>: Empty text and terminal punctuation branches.</li><li><code>AppError</code>: Factory methods and the implicit branch in the constructor.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We decided to implement exhaustive unit tests to hit every line and branch in the domain layer.</p><p>Key strategies implemented:</p><ol><li><strong>Mocking Restricted Environments</strong>: For <code>AppError</code>, we mocked the absence of <code>Error.captureStackTrace</code> to cover the fallback branch used in non-V8 environments (or transpilation-injected checks).</li><li><strong>Explicit Branch Testing</strong>: Forced <code>undefined</code> on optional properties (like <code>analysis.requirements</code>) to test AMBIGUOUS fallback logic.</li><li><strong>Keyword Boundary Testing</strong>: Added tests for <code>RequirementsExtractor</code> with text that ends abruptly without punctuation to verify regex split behavior.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Absolute Reliability</strong>: The core logic is now fully verified against edge cases.</li><li><strong>CI Gate</strong>: The pipeline now enforces 100% domain coverage, preventing any regressions in the core layer.</li><li><strong>Maintenance</strong>: Adding new domain features now requires 100% coverage by default, maintaining the high quality bar.</li></ul>',15)])])}const p=a(n,[["render",r]]);export{g as __pageData,p as default};
